// Xác thực chữ ký Crisp: HMAC-SHA256("[timestamp;raw_body]", hook secret). Sai/thiếu/cũ thì bỏ.
// n8n cần NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
const SECRET = 'REPLACE_CRISP_HOOK_SECRET';
const MAX_SKEW_S = 300;
const ALLOWED = ['message:send', 'message:received', 'session:set_segments', 'session:set_state', 'session:set_email'];
if (SECRET.startsWith('REPLACE_') || SECRET.length < 16) throw new Error('Crisp hook secret chưa được cấu hình');
const h = $input.first().json.headers || {};
const ts = String(h['x-crisp-request-timestamp'] || '');
const sig = String(h['x-crisp-signature'] || '');
if (!/^\d+$/.test(ts) || !/^[0-9a-f]{64}$/.test(sig)) return [];
const tsSeconds = ts.length > 11 ? Number(ts) / 1000 : Number(ts);
if (Math.abs(Date.now() / 1000 - tsSeconds) > MAX_SKEW_S) return [];
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = crypto.createHmac('sha256', SECRET).update('[' + ts + ';' + raw + ']').digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return [];
const b = JSON.parse(raw);
if (!ALLOWED.includes(b.event) || !b.website_id || !b.data) return [];
return [{ json: { p_event: { website_id: b.website_id, event: b.event, data: b.data } } }];
